begin;lock table public.campaigns,public.campaign_content_entries,public.campaign_state_fragments,public.campaign_character_versions,public.official_content_entries in share row exclusive mode;do $text$ begin if(select state_revision from public.campaigns where id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd')<>1712 then raise exception 'ITEM_TEXT_CAMPAIGN_CONFLICT';end if;if not exists(select 1 from public.campaign_content_entries t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:b3561afd4baeeaff9340d6cf' and md5(to_jsonb(t)::text)='c80699910c24439e4bc0ea76e230195c')then raise exception 'ITEM_TEXT_CONFLICT:ece:official:equipment:es:b3561afd4baeeaff9340d6cf';end if;update public.campaign_content_entries set payload=jsonb_set(jsonb_set(jsonb_set(jsonb_set(payload,'{description}',$text_c667310c3c3c17d7$"Objeto · Precio base · Peso\nUtensilios de cocina · 2 pp · 1 lb\n\nUtensilios de cocina. Esta caja de hojalata contiene una copa y cubiertos sencillos. Se cierra al unirse dos mitades, una de las cuales puede servir como sartén y la otra, como plato o cuenco poco profundo.\n\nEsta obra incluye materiales extraídos del Documento de referencia del sistema 5.1 (‘SRD 5.1’) de Wizards of the Coast LLC, que está disponible en https://dnd.wizards.com/es/resources/systems-reference-document. El SRD 5.1 tiene la licencia Creative Commons Atribución/Reconocimiento 4.0 Licencia Pública Internacional, que está disponible en https://creativecommons.org/licenses/by/4.0/legalcode.es."$text_c667310c3c3c17d7$::jsonb,true),'{features}',$text_17df154811e76464$[{"id":"mundane-use","kind":"other","name":"Uso del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Utensilios de cocina. Esta caja de hojalata contiene una copa y cubiertos sencillos. Se cierra al unirse dos mitades, una de las cuales puede servir como sartén y la otra, como plato o cuenco poco profundo.\n\nDuración: Mientras se cumplen los requisitos..","showInActions":false}]$text_17df154811e76464$::jsonb,true),'{rules,definition,description}',$text_d91a6351d35012ce$[{"id":"official-table","rows":[["Utensilios de cocina","2 pp","1 lb"]],"type":"table","columns":["Objeto","Precio base","Peso"],"section":"description","sourceIds":["srd-5.1-en-equipment"],"provenance":"reviewed-translation"},{"id":"official-rules-0","text":"Utensilios de cocina. Esta caja de hojalata contiene una copa y cubiertos sencillos. Se cierra al unirse dos mitades, una de las cuales puede servir como sartén y la otra, como plato o cuenco poco profundo.","type":"paragraph","section":"rules","sourceIds":["srd-5.1-es-equipment"],"provenance":"official-spanish"}]$text_d91a6351d35012ce$::jsonb,true),'{rules,definition,capabilities}',(select coalesce(jsonb_agg(cap||jsonb_build_object('textBlockIds',coalesce((select jsonb_agg(id) from jsonb_array_elements_text(cap->'textBlockIds')id where $text_bb21ed74d2f9e9dc$["official-table","official-rules-0"]$text_bb21ed74d2f9e9dc$::jsonb?id),jsonb_build_array('official-table')))),'[]'::jsonb) from jsonb_array_elements(payload#>'{rules,definition,capabilities}')cap),true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:b3561afd4baeeaff9340d6cf';
if not exists(select 1 from public.campaign_content_entries t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:b4e79a3cd24aec59f54d746c' and md5(to_jsonb(t)::text)='f582bdc0f37fa077c254961e9d3eca6a')then raise exception 'ITEM_TEXT_CONFLICT:ece:official:equipment:es:b4e79a3cd24aec59f54d746c';end if;update public.campaign_content_entries set payload=jsonb_set(jsonb_set(payload,'{features}',$text_b10dc0571e393288$[{"id":"official-assisted-rule","kind":"other","name":"Reglas del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Esta túnica está decorada con un estampado de ojos. Mientras la lleves puesta, obtendrás los siguientes beneficios: • La túnica te permite ver en todas las direcciones y tienes ventaja en las pruebas de Sabiduría (Percepción) que dependan de la vista. • Tienes visión en la oscuridad hasta 36 m. • Puedes ver criaturas y objetos invisibles, además de ver en el Plano Etéreo, hasta una distancia de 36 m.\n\nNo se puede hacer que los ojos de la túnica se cierren o aparten la mirada. Aunque tú hagas ambas cosas con tus propios ojos, no se considerará que lo estés haciendo mientras lleves puesta esta túnica.\n\nSi se lanza un conjuro luz sobre la túnica o un conjuro luz del día a 1,5 m o menos de ella, quedarás cegado durante 1 minuto. Al final de cada uno de tus turnos, podrás hacer una tirada de salvación de Constitución (con CD 11 para luz o CD 15 para luz del día) y, si la superas, dejarás de estar cegado.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_b10dc0571e393288$::jsonb,true),'{rules,personalDescription}',$text_9fff02b7f3eaf6cf$"Esta túnica está decorada con un estampado de ojos. Mientras la lleves puesta, obtendrás los siguientes beneficios:\n\nLa túnica te permite ver en todas direcciones y te propor ciona ventaja en las pruebas de Sabiduría (Percepción) que dependan de la vista.\n\nVisión en la Oscuridad hasta una distancia de 120 pies.\n\nPuedes ver dentro del Plano Etéreo, así como a criaturas y objetos invisibles, hasta una distancia de 120 pies.\n\nLos ojos de la túnica no pueden cerrarse o desviar la mirada. Aunque tú sí eres capaz de hacer estas dos cosas, no se considera que lo estés haciendo mientras lleves esta túnica. Si se lanza el conjuro luz sobre la túnica, o el conjuro luz del día a 5 pies de la túnica, quedarás cegado durante 1 minuto. Al final de cada uno de tus turnos, puedes realizar una tirada de salvación de Constitución CD (CD 11 para luz y CD 15 para luz del día), la ceguera terminará si tienes éxito."$text_9fff02b7f3eaf6cf$::jsonb,true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:b4e79a3cd24aec59f54d746c';
if not exists(select 1 from public.campaign_content_entries t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:b4f84e86590127efe768a95f' and md5(to_jsonb(t)::text)='9e0701ef276e943be94fd37daf39413a')then raise exception 'ITEM_TEXT_CONFLICT:ece:official:equipment:es:b4f84e86590127efe768a95f';end if;update public.campaign_content_entries set payload=jsonb_set(payload,'{features}',$text_2f559f340aeab2a5$[{"id":"official-2014-rule","kind":"other","name":"Reglas de la variante","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Recibes un bonificador de +1 a las tiradas de ataque y de daño que hagas con esta arma mágica. El bonificador aumenta a +3 cuando usas la maza para atacar a un autómata.\n\nSi sacas un 20 en una tirada de ataque con esta arma, el objetivo sufrirá 2d6 de daño contundente adicional o 4d6 de daño contundente adicional si es un autómata. Si a un autómata le quedan 25 puntos de golpe o menos tras sufrir este daño, será destruido.\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_2f559f340aeab2a5$::jsonb,true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:b4f84e86590127efe768a95f';
if not exists(select 1 from public.campaign_content_entries t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:b51442c4161640e2e7a37f88' and md5(to_jsonb(t)::text)='d6027ad3f91b66486da2c6fba1461a3e')then raise exception 'ITEM_TEXT_CONFLICT:ece:official:equipment:es:b51442c4161640e2e7a37f88';end if;update public.campaign_content_entries set payload=jsonb_set(payload,'{features}',$text_9d7a8b13ac6a9095$[{"id":"official-assisted-rule","kind":"other","name":"Reglas del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Este objeto parece una caja de madera que mide 30 cm de largo, 15 cm de ancho y 15 cm de profundidad. Pesa 2 kg y flota. Puede abrirse para guardar objetos en su interior. Además, este objeto tiene tres palabras de activación y cada una requiere una acción para pronunciarla.\n\nLa primera hace que la caja se despliegue y forme un bote de 3 m de largo, 1,2 m de ancho y 60 cm de profundidad. Este bote tiene un par de remos, un ancla, un mástil y una vela latina. El bote puede alojar a cuatro criaturas Medianas con comodidad.\n\nLa segunda hace que la caja se despliegue y forme un barco de 7,2 m de largo, 2,4 m de ancho y 1,8 m de profundidad. Este barco posee una cubierta, bancadas de remo, cinco juegos de remos, un timón de espadilla, un ancla, un camarote de cubierta y un mástil con una vela cuadrada. El barco puede alojar a quince criaturas Medianas con comodidad.\n\nCuando la caja se convierte en una embarcación, adopta el peso de una embarcación de su tamaño y cualquier cosa que contuviera la caja permanece en su interior.\n\nLa tercera palabra de activación hace que se pliegue de nuevo y recupere su forma de caja, siempre y cuando no haya criaturas a bordo. Cualquier objeto que contenga la embarcación y no quepa en la caja permanecerá fuera de ella cuando se pliegue. Los que sí quepan en la caja permanecerán dentro.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_9d7a8b13ac6a9095$::jsonb,true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:b51442c4161640e2e7a37f88';
if not exists(select 1 from public.campaign_content_entries t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:b516b1395030f3d0e44512e6' and md5(to_jsonb(t)::text)='bdd92b8aeb92abce26f065be6ff872b5')then raise exception 'ITEM_TEXT_CONFLICT:ece:official:equipment:es:b516b1395030f3d0e44512e6';end if;update public.campaign_content_entries set payload=jsonb_set(payload,'{features}',$text_e9cf38e8596f211e$[{"id":"official-assisted-rule","kind":"other","name":"Reglas del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Este tubo de metal hueco mide alrededor de 30 cm de largo y pesa 0,5 kg. Como acción, puedes tocarlo y apuntar con él hacia un objeto que esté a 36 m o menos de ti que se pueda abrir, como una puerta, una tapa o una cerradura. El carillón emite un tono nítido y una cerradura o cerrojo del objeto se abrirá salvo que el sonido no pueda alcanzarlo. Si no queda ninguna cerradura o cierre, el objeto mismo se abrirá.\n\nEl carillón puede utilizarse diez veces. Tras el décimo uso, se resquebraja y se vuelve inútil.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_e9cf38e8596f211e$::jsonb,true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:b516b1395030f3d0e44512e6';
if not exists(select 1 from public.campaign_content_entries t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:b53f1d3eda845184553e548c' and md5(to_jsonb(t)::text)='759d759de26e7f695b5d14e624381c14')then raise exception 'ITEM_TEXT_CONFLICT:ece:official:equipment:es:b53f1d3eda845184553e548c';end if;update public.campaign_content_entries set payload=jsonb_set(jsonb_set(jsonb_set(payload,'{features}',$text_4543b46f281f3b43$[{"id":"vicious-natural-20","kind":"other","name":"Daño adicional con un 20 natural","uses":null,"order":0,"rolls":[{"mode":"normal","label":"Daño condicionado","expression":"7"}],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Cuando sacas un 20 en la tirada de ataque con esta arma mágica, el objetivo recibe 7 puntos de daño adicional del tipo de daño del arma.\n\nDuración: Mientras se cumplen los requisitos..","showInActions":false}]$text_4543b46f281f3b43$::jsonb,true),'{rules,definition,description}',$text_84965bf2bdfe287b$[{"id":"official-base-table","rows":[["Dardo","5 pc","0.25 lb","1d4 perforante","+0","Sutil, Arrojadiza","20/60"]],"type":"table","columns":["Objeto base","Precio del objeto mundano","Peso","Daño base","Bonificación mágica al ataque","Propiedades","Alcance normal/largo (pies)"],"section":"description","sourceIds":["srd-5.1-en-equipment"],"provenance":"reviewed-translation"},{"id":"property-finesse","text":"Sutil. Cuando ataques con un arma sutil, podrás elegir realizar las tiradas de ataque y de daño con el modificador por Fuerza o con el modificador por Destreza. Eso sí, deberás usar el mismo modificador para ambas tiradas.","type":"paragraph","section":"rules","sourceIds":["srd-5.1-es-equipment"],"provenance":"official-spanish"},{"id":"property-thrown","text":"Arrojadiza. Si un arma tiene esta propiedad, puedes lanzarla para realizar un ataque a distancia. Si se trata de un arma cuerpo a cuerpo, harás las tiradas de ataque y de daño con el mismo modificador que emplearías para hacer un ataque cuerpo a cuerpo con el arma. Por ejemplo, si lanzas un hacha de mano, utilizarás tu Fuerza, pero si arrojas una daga, podrás elegir entre usar la Fuerza o la Destreza, ya que la daga también posee la propiedad “sutil”.","type":"paragraph","section":"rules","sourceIds":["srd-5.1-es-equipment"],"provenance":"official-spanish"},{"id":"family-rule","text":"Cuando sacas un 20 en la tirada de ataque con esta arma mágica, el objetivo recibe 7 puntos de daño adicional del tipo de daño del arma.","type":"paragraph","section":"rules","sourceIds":["dmg-2014-vicious"],"provenance":"reviewed-translation"}]$text_84965bf2bdfe287b$::jsonb,true),'{rules,definition,capabilities}',(select coalesce(jsonb_agg(cap||jsonb_build_object('textBlockIds',coalesce((select jsonb_agg(id) from jsonb_array_elements_text(cap->'textBlockIds')id where $text_9d262c87d818d184$["official-base-table","property-finesse","property-thrown","family-rule"]$text_9d262c87d818d184$::jsonb?id),jsonb_build_array('official-base-table')))),'[]'::jsonb) from jsonb_array_elements(payload#>'{rules,definition,capabilities}')cap),true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:b53f1d3eda845184553e548c';
if not exists(select 1 from public.campaign_content_entries t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:b55296bd6257b7ae74153624' and md5(to_jsonb(t)::text)='bff6a45ceb403214932539155af9b845')then raise exception 'ITEM_TEXT_CONFLICT:ece:official:equipment:es:b55296bd6257b7ae74153624';end if;update public.campaign_content_entries set payload=jsonb_set(jsonb_set(jsonb_set(jsonb_set(payload,'{description}',$text_3bade0ddf6f5d7f7$"Objeto · Precio base · Peso\nCuerda de seda (50 pies) · 10 po · 5 lb\n\nCuerda. La cuerda, tanto si es de cáñamo como si es de seda, tiene 2 puntos de golpe y, para romperla, es necesaria una prueba de Fuerza con CD 17.\n\nEsta obra incluye materiales extraídos del Documento de referencia del sistema 5.1 (‘SRD 5.1’) de Wizards of the Coast LLC, que está disponible en https://dnd.wizards.com/es/resources/systems-reference-document. El SRD 5.1 tiene la licencia Creative Commons Atribución/Reconocimiento 4.0 Licencia Pública Internacional, que está disponible en https://creativecommons.org/licenses/by/4.0/legalcode.es."$text_3bade0ddf6f5d7f7$::jsonb,true),'{features}',$text_be24ea40c71d093b$[{"id":"mundane-use","kind":"other","name":"Uso del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Cuerda. La cuerda, tanto si es de cáñamo como si es de seda, tiene 2 puntos de golpe y, para romperla, es necesaria una prueba de Fuerza con CD 17.\n\nDuración: Mientras se cumplen los requisitos..","showInActions":false}]$text_be24ea40c71d093b$::jsonb,true),'{rules,definition,description}',$text_7901198c794c897c$[{"id":"official-table","rows":[["Cuerda de seda (50 pies)","10 po","5 lb"]],"type":"table","columns":["Objeto","Precio base","Peso"],"section":"description","sourceIds":["srd-5.1-en-equipment"],"provenance":"reviewed-translation"},{"id":"official-rules-0","text":"Cuerda. La cuerda, tanto si es de cáñamo como si es de seda, tiene 2 puntos de golpe y, para romperla, es necesaria una prueba de Fuerza con CD 17.","type":"paragraph","section":"rules","sourceIds":["srd-5.1-es-equipment"],"provenance":"official-spanish"}]$text_7901198c794c897c$::jsonb,true),'{rules,definition,capabilities}',(select coalesce(jsonb_agg(cap||jsonb_build_object('textBlockIds',coalesce((select jsonb_agg(id) from jsonb_array_elements_text(cap->'textBlockIds')id where $text_bb21ed74d2f9e9dc$["official-table","official-rules-0"]$text_bb21ed74d2f9e9dc$::jsonb?id),jsonb_build_array('official-table')))),'[]'::jsonb) from jsonb_array_elements(payload#>'{rules,definition,capabilities}')cap),true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:b55296bd6257b7ae74153624';
if not exists(select 1 from public.campaign_content_entries t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:b6c252fadf815e5461e8d2a1' and md5(to_jsonb(t)::text)='71ba4524ba39cc4a1ac87a68263264b9')then raise exception 'ITEM_TEXT_CONFLICT:ece:official:equipment:es:b6c252fadf815e5461e8d2a1';end if;update public.campaign_content_entries set payload=jsonb_set(payload,'{features}',$text_6a02f799c3d2ea30$[{"id":"official-assisted-rule","kind":"other","name":"Reglas del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"El frasco de esta poción parece vacío, pero, al mismo tiempo, da la impresión de contener líquido. Cuando la bebas, te volverás invisible durante 1 hora. Cualquier cosa que vistas o lleves será invisible también. El efecto acabará antes de tiempo si atacas o lanzas un conjuro.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_6a02f799c3d2ea30$::jsonb,true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:b6c252fadf815e5461e8d2a1';
if not exists(select 1 from public.campaign_content_entries t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:b70bcbd36262a7a83ce6943f' and md5(to_jsonb(t)::text)='0e514295b07a0f7e26f5d3b7335a914f')then raise exception 'ITEM_TEXT_CONFLICT:ece:official:equipment:es:b70bcbd36262a7a83ce6943f';end if;update public.campaign_content_entries set payload=jsonb_set(payload,'{features}',$text_a20158e61a77c8ee$[{"id":"official-2014-rule","kind":"action","name":"Beber o administrar","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Cuando bebas esta poción, obtendrás el efecto de “reducir” del conjuro agrandar/reducir durante 1d4 horas (no requiere concentración). El color rojo del líquido de la poción se contrae continuamente hasta quedar reducido a una gota diminuta y, a continuación, se expande para teñir el líquido transparente que la rodea. Si agitas la botella, no se interrumpirá el proceso.\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":true}]$text_a20158e61a77c8ee$::jsonb,true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:b70bcbd36262a7a83ce6943f';
if not exists(select 1 from public.campaign_content_entries t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:b70c41be552f3dc614f1f4ad' and md5(to_jsonb(t)::text)='b82be73ac589bd7a7bfcf832c1d6c8ba')then raise exception 'ITEM_TEXT_CONFLICT:ece:official:equipment:es:b70c41be552f3dc614f1f4ad';end if;update public.campaign_content_entries set payload=jsonb_set(payload,'{features}',$text_8cb44176861add58$[{"id":"legacy-bonus-0","kind":"passive","name":"AC","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Otorga una bonificación de +1 a la CA.","showInActions":false},{"id":"official-2014-rule","kind":"other","name":"Reglas de la variante","uses":null,"order":1,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Mientras lleves esta armadura, obtendrás un bonificador de +1 a la CA. También puedes usar una acción adicional para pronunciar la palabra de activación y hacer que la armadura adopte el aspecto de una vestimenta normal o de otro tipo de armadura. Tú decides su apariencia, incluidos el color, estilo y accesorios, pero la armadura mantiene su peso y tamaño normales. La apariencia ilusoria dura hasta que emplees esta propiedad de nuevo o te quites la armadura.\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_8cb44176861add58$::jsonb,true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:b70c41be552f3dc614f1f4ad';
if not exists(select 1 from public.campaign_content_entries t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:b730d94858e9db458b9f67f2' and md5(to_jsonb(t)::text)='33dba387c817a22e1ca3b1d57dac976f')then raise exception 'ITEM_TEXT_CONFLICT:ece:official:equipment:es:b730d94858e9db458b9f67f2';end if;update public.campaign_content_entries set payload=jsonb_set(jsonb_set(jsonb_set(jsonb_set(payload,'{description}',$text_1c0d2a3f4c2897ea$"Objeto · Precio base · Peso\nEstuche para mapas o pergaminos · 1 po · 1 lb\n\nEstuche para mapas o pergaminos. Esta caja de cuero cilíndrica puede contener hasta diez hojas de papel o cinco hojas de pergamino, enrolladas en ambos casos.\n\nEsta obra incluye materiales extraídos del Documento de referencia del sistema 5.1 (‘SRD 5.1’) de Wizards of the Coast LLC, que está disponible en https://dnd.wizards.com/es/resources/systems-reference-document. El SRD 5.1 tiene la licencia Creative Commons Atribución/Reconocimiento 4.0 Licencia Pública Internacional, que está disponible en https://creativecommons.org/licenses/by/4.0/legalcode.es."$text_1c0d2a3f4c2897ea$::jsonb,true),'{features}',$text_73d8460653650a2f$[{"id":"mundane-use","kind":"other","name":"Uso del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Estuche para mapas o pergaminos. Esta caja de cuero cilíndrica puede contener hasta diez hojas de papel o cinco hojas de pergamino, enrolladas en ambos casos.\n\nDuración: Mientras se cumplen los requisitos..","showInActions":false}]$text_73d8460653650a2f$::jsonb,true),'{rules,definition,description}',$text_8784c36495e48939$[{"id":"official-table","rows":[["Estuche para mapas o pergaminos","1 po","1 lb"]],"type":"table","columns":["Objeto","Precio base","Peso"],"section":"description","sourceIds":["srd-5.1-en-equipment"],"provenance":"reviewed-translation"},{"id":"official-rules-0","text":"Estuche para mapas o pergaminos. Esta caja de cuero cilíndrica puede contener hasta diez hojas de papel o cinco hojas de pergamino, enrolladas en ambos casos.","type":"paragraph","section":"rules","sourceIds":["srd-5.1-es-equipment"],"provenance":"official-spanish"}]$text_8784c36495e48939$::jsonb,true),'{rules,definition,capabilities}',(select coalesce(jsonb_agg(cap||jsonb_build_object('textBlockIds',coalesce((select jsonb_agg(id) from jsonb_array_elements_text(cap->'textBlockIds')id where $text_bb21ed74d2f9e9dc$["official-table","official-rules-0"]$text_bb21ed74d2f9e9dc$::jsonb?id),jsonb_build_array('official-table')))),'[]'::jsonb) from jsonb_array_elements(payload#>'{rules,definition,capabilities}')cap),true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:b730d94858e9db458b9f67f2';
if not exists(select 1 from public.campaign_content_entries t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:b87f89b4ff0c0569889ebd32' and md5(to_jsonb(t)::text)='d40d27e7a6d2078613f6dbc4f77ae0da')then raise exception 'ITEM_TEXT_CONFLICT:ece:official:equipment:es:b87f89b4ff0c0569889ebd32';end if;update public.campaign_content_entries set payload=jsonb_set(jsonb_set(payload,'{features}',$text_79d15a2b9ac643a0$[{"id":"official-2014-rule","kind":"other","name":"Reglas de la variante","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Recibes un bonificador de +3 a las tiradas de ataque y de daño que hagas con esta arma mágica.\n\nLa primera vez que ataques con la espada en cada uno de tus turnos, puedes transferir parte o todo el bonificador de la espada a tu Clase de Armadura en vez de usar el bonificador en los ataques de ese turno. Por ejemplo, puedes reducir el bonificador a tus tiradas de ataque y de daño a +1 y obtener un bonificador de +2 a tu CA. Los bonificadores ajustados permanecen en vigor hasta el principio de tu siguiente turno, aunque debes empuñar la espada para aprovechar el bonificador a la CA que confiere.\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_79d15a2b9ac643a0$::jsonb,true),'{rules,personalDescription}',$text_9b5d632c315d4cc9$"Obtienes un bonificador de +3 a las tiradas de ataque y daño realizadas con esta arma mágica. \nLa primera vez que ataques con la espada en cada uno de tus turnos, puedes transferir parte o la totalidad del bonificador de la espada a tu Clase de Armadura, en lugar de usar el bonificador en cualquier ataque de ese turno. Por ejemplo, podrías reducir el bonificador a tus tiradas de ataque y daño a +1 y obtener un bonificador de +2 a la CA. Los bonificadores ajustados permanecen en efecto hasta el comienzo de tu siguiente turno, aunque debes sostener la espada para obtener un bonificador a la CA de ella."$text_9b5d632c315d4cc9$::jsonb,true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:b87f89b4ff0c0569889ebd32';
if not exists(select 1 from public.campaign_content_entries t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:b8c8c1da43606dcf462e765f' and md5(to_jsonb(t)::text)='27c76d67345ee1feee69788314f91942')then raise exception 'ITEM_TEXT_CONFLICT:ece:official:equipment:es:b8c8c1da43606dcf462e765f';end if;update public.campaign_content_entries set payload=jsonb_set(jsonb_set(jsonb_set(jsonb_set(payload,'{description}',$text_346ce798f07d5474$"Objeto · Precio base · Peso\nCuerda de cáñamo (50 pies) · 1 po · 10 lb\n\nCuerda. La cuerda, tanto si es de cáñamo como si es de seda, tiene 2 puntos de golpe y, para romperla, es necesaria una prueba de Fuerza con CD 17.\n\nEsta obra incluye materiales extraídos del Documento de referencia del sistema 5.1 (‘SRD 5.1’) de Wizards of the Coast LLC, que está disponible en https://dnd.wizards.com/es/resources/systems-reference-document. El SRD 5.1 tiene la licencia Creative Commons Atribución/Reconocimiento 4.0 Licencia Pública Internacional, que está disponible en https://creativecommons.org/licenses/by/4.0/legalcode.es."$text_346ce798f07d5474$::jsonb,true),'{features}',$text_be24ea40c71d093b$[{"id":"mundane-use","kind":"other","name":"Uso del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Cuerda. La cuerda, tanto si es de cáñamo como si es de seda, tiene 2 puntos de golpe y, para romperla, es necesaria una prueba de Fuerza con CD 17.\n\nDuración: Mientras se cumplen los requisitos..","showInActions":false}]$text_be24ea40c71d093b$::jsonb,true),'{rules,definition,description}',$text_8cedde3dc4b4e343$[{"id":"official-table","rows":[["Cuerda de cáñamo (50 pies)","1 po","10 lb"]],"type":"table","columns":["Objeto","Precio base","Peso"],"section":"description","sourceIds":["srd-5.1-en-equipment"],"provenance":"reviewed-translation"},{"id":"official-rules-0","text":"Cuerda. La cuerda, tanto si es de cáñamo como si es de seda, tiene 2 puntos de golpe y, para romperla, es necesaria una prueba de Fuerza con CD 17.","type":"paragraph","section":"rules","sourceIds":["srd-5.1-es-equipment"],"provenance":"official-spanish"}]$text_8cedde3dc4b4e343$::jsonb,true),'{rules,definition,capabilities}',(select coalesce(jsonb_agg(cap||jsonb_build_object('textBlockIds',coalesce((select jsonb_agg(id) from jsonb_array_elements_text(cap->'textBlockIds')id where $text_bb21ed74d2f9e9dc$["official-table","official-rules-0"]$text_bb21ed74d2f9e9dc$::jsonb?id),jsonb_build_array('official-table')))),'[]'::jsonb) from jsonb_array_elements(payload#>'{rules,definition,capabilities}')cap),true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:b8c8c1da43606dcf462e765f';
if not exists(select 1 from public.campaign_content_entries t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:b97890f2fdedbce0fbe843c2' and md5(to_jsonb(t)::text)='95095a0bd71ecfa9cd786164da1af423')then raise exception 'ITEM_TEXT_CONFLICT:ece:official:equipment:es:b97890f2fdedbce0fbe843c2';end if;update public.campaign_content_entries set payload=jsonb_set(payload,'{features}',$text_8ee5d19ae1554acb$[{"id":"legacy-bonus-0","kind":"passive","name":"SpellAttackModifier","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Obtienes un bonificador de +2 a las tiradas de ataque de hechizos y a las CD de las tiradas de salvación de tus hechizos.","showInActions":false},{"id":"official-assisted-rule","kind":"other","name":"Reglas del objeto","uses":null,"order":1,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Este objeto simboliza el mal impenitente. Una criatura cuyo alineamiento no sea ni bueno ni malvado sufrirá 6d6 de daño necrótico si lo toca. En cambio, si es de alineamiento bueno, sufrirá 8d6 de daño necrótico. En ambos casos, la criatura sufrirá el daño de nuevo cada vez que sostenga o lleve puesto el talismán al terminar su turno.\n\nSi eres un clérigo o paladín malvado, puedes usar el talismán como símbolo sagrado y obtienes un bonificador de +2 a las tiradas de ataque de conjuro mientras lo lleves puesto o lo sostengas.\n\nEl talismán tiene 6 cargas. Si lo llevas puesto o lo sostienes, puedes usar una acción para gastar 1 de sus cargas y elegir una criatura que puedas ver en el suelo a 36 m o menos de ti. Si el objetivo tiene alineamiento bueno, una grieta ardiente se abrirá bajo él. Deberá superar una tirada de salvación de Destreza con CD 20 o se caerá por la grieta y será destruido sin dejar ningún resto mortal. A continuación, la grieta se cerrará y no quedará ni huella de su existencia. Cuando gastes la última carga, el talismán se disolverá en un limo apestoso y se destruirá.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_8ee5d19ae1554acb$::jsonb,true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:b97890f2fdedbce0fbe843c2';
if not exists(select 1 from public.campaign_content_entries t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:b98496842c9011838d19a5f5' and md5(to_jsonb(t)::text)='e492f2de3d9428dac79bab6624e34ab4')then raise exception 'ITEM_TEXT_CONFLICT:ece:official:equipment:es:b98496842c9011838d19a5f5';end if;update public.campaign_content_entries set payload=jsonb_set(jsonb_set(payload,'{features}',$text_152647ecf02599bc$[{"id":"official-2014-rule","kind":"other","name":"Reglas de la variante","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Esta túnica está cubierta de parches de tela de diversas formas y colores. Mientras la lleves puesta, podrás utilizar una acción para quitar uno de los parches y hacer que se convierta en el objeto o criatura que representa. En cuanto hayas quitado el último parche, la túnica se volverá una prenda normal y corriente.\n\nLa túnica tiene dos de cada uno de los siguientes parches: • Daga. • Linterna de ojo de buey (llena y encendida). • Espejo de acero. • Vara de 3 m. • Cuerda de cáñamo (15 m, enrollada). • Saco.\n\nAdemás, la túnica tiene otros 4d4 parches. Tu GM elige los parches o los determina al azar.\n\n01–08 · Bolsa con 100 po\n09–15 · Cofre de plata (30 cm de largo, 15 cm de ancho y de alto) con un valor de 500 po\n16–22 · Puerta de hierro (hasta 3 m de ancho y 3 de alto, atrancada por el lado que elijas), que puedes colocar en una abertura que esté a tu alcance. Se adecuará al tamaño de la abertura y se instalará y afianzará ella sola\n23–30 · 10 gemas con un valor de 100 po cada una\n31–44 · Escalera de madera (7,2 m de largo)\n45–51 · Un caballo de monta con alforjas\n52–59 · Pozo (un cubo de 3 m de lado), que puedes colocar en el suelo a 3 m o menos de ti\n60–68 · 4 pociones de curación\n69–75 · Bote de remos (3,6 m de largo)\n76–83 · Pergamino con un conjuro de nivel 1 a 3\n84–90 · 2 mastines\n91–96 · Ventana (60 cm por 1,2 m, con una profundidad de hasta 60 cm), que puedes colocar en una superficie vertical que esté a tu alcance\n97–00 · Ariete portátil\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_152647ecf02599bc$::jsonb,true),'{rules,personalDescription}',$text_fcbd48c8a3f1ad01$"Esta túnica está cubierta de parches de tela de diferentes formas y colores. Mientras la lleves puesta, puedes usar una acción para descoser uno de ellos, haciendo que se convierta en el objeto que representa. Una vez que el último parche haya sido quitado, la túnica se convierte en una prenda normal. Tiene dos de cada uno de los siguientes parches:\n\nDaga.\nLinterna de ojo de buey (llena y encendida).\nEspejo de acero.\nVara de 10 pies.\nCuerda de cáñamo (50 pies, enrollada).\nSaco.\n\nAdemás, la túnica posee otros 4d4 parches. El DM los elige o determina al azar.\n\n01-08 - Bolsa de l 00 po\n09-15 - Cofre de plata (l pie de largo, 6 pulgadas de ancho y fondo) con un valor de 500 po\n16-22 - Puerta de hierro (hasta l O pies de ancho y l O pies de alto, atrancada desde el lado de tu elección), que puedes situar en una abertura que se encuentre a tu alcance; se ajustará un máximo de 2 pies a la abertura, instalándose y afianzándose con bisagras.\n23-30 - 10 gemas con un valor de 100 po cada una\n31-44 - Escalera de madera (24 pies de largo)\n45-51 - Un caballo de monta con alforjas (ver el perfil en el Monster Manual)\n52-59 - Pozo (un cubo de 10 pies de lado), que puedes colocar en el suelo en un punto situado a 10 pies o menos de ti\n60-68 - 4 Pociones de curación\n69-75 - Bote de remo (12 pies de eslora)\n76-83 - Pergamino con un conjuro de nivel l a 3\n84-90 - 2 Mastines\n91-96 - Ventana (2 por 4 pies, hasta 2 pies de profundidad), que puedes colocar en una superficie vertical que se encuentre a tu alcance\n97-00 - Ariete portátil"$text_fcbd48c8a3f1ad01$::jsonb,true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:b98496842c9011838d19a5f5';
if not exists(select 1 from public.campaign_content_entries t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:bb14d0105c6f290c8ccf2eaa' and md5(to_jsonb(t)::text)='5f159c95071409acaec129a209ba34a4')then raise exception 'ITEM_TEXT_CONFLICT:ece:official:equipment:es:bb14d0105c6f290c8ccf2eaa';end if;update public.campaign_content_entries set payload=jsonb_set(jsonb_set(jsonb_set(payload,'{features}',$text_4543b46f281f3b43$[{"id":"vicious-natural-20","kind":"other","name":"Daño adicional con un 20 natural","uses":null,"order":0,"rolls":[{"mode":"normal","label":"Daño condicionado","expression":"7"}],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Cuando sacas un 20 en la tirada de ataque con esta arma mágica, el objetivo recibe 7 puntos de daño adicional del tipo de daño del arma.\n\nDuración: Mientras se cumplen los requisitos..","showInActions":false}]$text_4543b46f281f3b43$::jsonb,true),'{rules,definition,description}',$text_c506ffd3b50bb694$[{"id":"official-base-table","rows":[["Bastón","2 pp","4 lb","1d6 contundente","+0","Versátil","1d8"]],"type":"table","columns":["Objeto base","Precio del objeto mundano","Peso","Daño base","Bonificación mágica al ataque","Propiedades","Daño versátil"],"section":"description","sourceIds":["srd-5.1-en-equipment"],"provenance":"reviewed-translation"},{"id":"property-versatile","text":"Versátil. Estas armas pueden utilizarse con una o con dos manos. Tras esta propiedad aparece entre paréntesis un valor de daño, que será el que uses cuando emplees esta arma a dos manos para hacer un ataque cuerpo a cuerpo.","type":"paragraph","section":"rules","sourceIds":["srd-5.1-es-equipment"],"provenance":"official-spanish"},{"id":"family-rule","text":"Cuando sacas un 20 en la tirada de ataque con esta arma mágica, el objetivo recibe 7 puntos de daño adicional del tipo de daño del arma.","type":"paragraph","section":"rules","sourceIds":["dmg-2014-vicious"],"provenance":"reviewed-translation"}]$text_c506ffd3b50bb694$::jsonb,true),'{rules,definition,capabilities}',(select coalesce(jsonb_agg(cap||jsonb_build_object('textBlockIds',coalesce((select jsonb_agg(id) from jsonb_array_elements_text(cap->'textBlockIds')id where $text_5488757723349d23$["official-base-table","property-versatile","family-rule"]$text_5488757723349d23$::jsonb?id),jsonb_build_array('official-base-table')))),'[]'::jsonb) from jsonb_array_elements(payload#>'{rules,definition,capabilities}')cap),true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:bb14d0105c6f290c8ccf2eaa';
if not exists(select 1 from public.campaign_content_entries t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:bbb14cd18a2f266a4b6f3921' and md5(to_jsonb(t)::text)='0bef78cf33d64a320dfcac3f801828b0')then raise exception 'ITEM_TEXT_CONFLICT:ece:official:equipment:es:bbb14cd18a2f266a4b6f3921';end if;update public.campaign_content_entries set payload=jsonb_set(jsonb_set(payload,'{features}',$text_78cacd5c998f65d7$[{"id":"official-2014-rule","kind":"other","name":"Reglas de la variante","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Este anillo está vinculado a uno de los cuatro Planos Elementales. Tu GM elige el plano o lo determina al azar.\n\nMientras lo lleves puesto, tendrás ventaja en las tiradas de ataque contra elementales del plano vinculado y ellos tendrán desventaja en las tiradas de ataque contra ti. Además, tendrás acceso a ciertas propiedades en función del plano vinculado.\n\nEl anillo tiene 5 cargas. Recupera 1d4 +1 cargas empleadas cada día, al amanecer. Los conjuros lanzados desde el anillo tienen una CD de salvación de 17.\n\nAnillo de comandar elementales de agua. Puedes gastar 2 de las cargas del anillo para lanzar el conjuro dominar monstruo sobre un elemental de agua. Además, puedes permanecer de pie sobre superficies líquidas y andar por ellas como si fueran terreno firme. También puedes hablar y entender acuano.\n\nSi ayudas a matar a un elemental de agua mientras tengas sintonización con el anillo, accedes las siguientes propiedades adicionales: • Puedes respirar bajo el agua y obtienes una velocidad nadando igual a tu velocidad caminando. • Puedes lanzar los siguientes conjuros desde el anillo empleando las cargas necesarias: crear o destruir agua (1 carga), controlar agua (3 cargas), muro de hielo (3 cargas) o tormenta de hielo (2 cargas).\n\nAnillo de comandar elementales de aire. Puedes gastar 2 de las cargas del anillo para lanzar el conjuro dominar monstruo sobre un elemental de aire. Además, cuando caigas, descenderás 18 m por asalto y no sufrirás daño por la caída. También puedes hablar y entender aurano.\n\nSi ayudas a matar a un elemental de aire mientras tengas sintonización con el anillo, accedes las siguientes propiedades adicionales: • Tienes resistencia al daño de relámpago. • Tienes una velocidad volando igual a tu velocidad caminando y puedes levitar. • Puedes lanzar los siguientes conjuros desde el anillo empleando las cargas necesarias: muro de viento (1 carga), ráfaga de viento (2 cargas) o relámpago en cadena (3 cargas).\n\nAnillo de comandar elementales de fuego. Puedes gastar 2 de las cargas del anillo para lanzar el conjuro dominar monstruo sobre un elemental de fuego. Además, tienes resistencia al daño de fuego. También puedes hablar y entender ígneo.\n\nSi ayudas a matar a un elemental de fuego mientras tengas sintonización con el anillo, accedes las siguientes propiedades adicionales: • Eres inmune al daño de fuego. • Puedes lanzar los siguientes conjuros desde el anillo empleando las cargas necesarias: bola de fuego (2 cargas), manos ardientes (1 carga) o muro de fuego (3 cargas).\n\nAnillo de comandar elementales de tierra. Puedes gastar 2 de las cargas del anillo para lanzar el conjuro dominar monstruo sobre un elemental de tierra. Además, puedes moverte por terreno difícil compuesto de escombros, rocas o tierra como si fuera terreno normal. También puedes hablar y entender terrano.\n\nSi ayudas a matar a un elemental de tierra mientras tengas sintonización con el anillo, accedes las siguientes propiedades adicionales: • Tienes resistencia al daño de ácido. • Puedes moverte a través de tierra sólida o roca como si estas superficies fueran terreno difícil. Si acabas tu turno en ellas, irás a parar al espacio sin ocupar más cercano en el que estuviste por última vez. • Puedes lanzar los siguientes conjuros desde el anillo empleando las cargas necesarias: moldear la piedra (2 cargas), muro de piedra (3 cargas) o piel pétrea (3 cargas).\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_78cacd5c998f65d7$::jsonb,true),'{rules,personalDescription}',$text_f34cdc8cad0ad43c$"Este anillo está vinculado al Plano Elemental de la Tierra. Mientras lo lleves puesto, tendrás ventaja en las tiradas de ataque contra elementales de tierra, y ellos tendrán desventaja en las tiradas de ataque contra ti. Además, tendrás acceso a propiedades basadas en el Plano Elemental de la Tierra. El anillo tiene 5 cargas. Recupera 1d4 + 1 cargas gastadas diariamente al amanecer. Los conjuros lanzados desde el anillo tienen una CD de salvación de 17. Puedes gastar 2 de las cargas del anillo para lanzar dominar monstruo sobre un elemental de tierra. Además, puedes moverte en terreno difícil compuesto de escombros, rocas o tierra como si fuera terreno normal. También puedes hablar y entender terrano. Si ayudas a matar a un elemental de tierra mientras estás en sintonía con el anillo, obtendrás acceso a las siguientes propiedades adicionales:\n\n-Tienes resistencia al daño por ácido\n-Puedes moverte a través de tierra sólida o roca como si esas áreas fueran terreno difícil. Si terminas tu turno allí, serás enviado al espacio desocupado más cercano que ocupaste por última vez. -Puedes lanzar los siguientes hechizos desde el anillo, gastando la cantidad necesaria de cargas: forma de piedra (2 cargas), piel de piedra (3 cargas) o muro de piedra (3 cargas)."$text_f34cdc8cad0ad43c$::jsonb,true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:bbb14cd18a2f266a4b6f3921';
if not exists(select 1 from public.campaign_content_entries t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:bbea1bc3b1ff5ee755a3fe51' and md5(to_jsonb(t)::text)='36d9900bb990c064168646b1a408f45c')then raise exception 'ITEM_TEXT_CONFLICT:ece:official:equipment:es:bbea1bc3b1ff5ee755a3fe51';end if;update public.campaign_content_entries set payload=jsonb_set(jsonb_set(payload,'{features}',$text_265f412dd9875685$[{"id":"official-assisted-rule","kind":"other","name":"Reglas del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Recibes un bonificador de +1 a las tiradas de ataque y de daño que hagas con esta arma mágica.\n\nAzote de gigantes (requiere sintonización). Debes llevar un cinturón de fuerza de gigante (cualquier variedad) y unos guanteletes de fuerza de ogro para sintonizarte con esta arma. La sinto- nización acaba inmediatamente si te quitas uno de estos objetos. Mientras tengas sintonización con esta arma y la empuñes, tu puntuación de Fuerza aumentará en 4 y podrá pasar de 20, pero no de 30. Si sacas un 20 en una tirada de ataque con esta arma contra un gigante, este deberá superar una tirada de salvación de Constitución con CD 17 o morirá.\n\nAdemás, el martillo tiene 5 cargas. Mientras tengas sintonización con él, podrás gastar 1 carga y hacer un ataque con arma a distancia con el martillo lanzándolo como si tuviera la propiedad “arrojadiza”, con un alcance normal de 6 m y un alcance largo de 18 m. Si el ataque impacta, el martillo suelta un trueno audible a 90 m. El objetivo y todas las criaturas que estén a 9 m o menos de él deberán superar una tirada de salvación de Constitución con CD 17 o quedarán aturdidos hasta el final de tu siguiente turno. El martillo recupera 1d4 + 1 cargas empleadas cada día, al amanecer.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_265f412dd9875685$::jsonb,true),'{rules,personalDescription}',$text_ea039c77e84d66d9$"Obtienes un bono de +1 a las tiradas de ataque y daño realizadas con esta arma mágica.\n\nAzote del gigante (requiere armonización). Debes llevar un cinturón de fuerza de gigante (de cualquier variedad) y guanteletes de poder de ogro para armonizarte con esta arma. La armonización termina si te quitas cualquiera de esos objetos. Mientras estés armonizado con esta arma y la sostengas, tu puntuación de Fuerza aumenta en 4 y puede superar 20, pero no 30. Cuando sacas un 20 en una tirada de ataque realizada con esta arma contra un gigante, el gigante debe superar una tirada de salvación de Constitución CD 17 o morir.\nEl martillo también tiene 5 cargas. Mientras estés en sintonía con él, puedes gastar 1 carga y realizar un ataque con arma a distancia con el martillo, arrojándolo como si tuviera la propiedad de arrojarlo con un alcance normal de 20 pies y un alcance largo de 60 pies. Si el ataque impacta, el martillo desata un trueno audible a 300 pies. El objetivo y todas las criaturas a 30 pies de él deben superar una tirada de salvación de Constitución CD 17 o quedarán aturdidos hasta el final de tu siguiente turno. El martillo recupera 1d4 + 1 cargas gastadas diariamente al amanecer. La competencia con un mazo te permite añadir tu bonificador de competencia a la tirada de ataque para cualquier ataque que realices con él."$text_ea039c77e84d66d9$::jsonb,true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:bbea1bc3b1ff5ee755a3fe51';
