sonb_build_object('textBlockIds',coalesce((select jsonb_agg(id) from jsonb_array_elements_text(cap->'textBlockIds')id where $text_a0bde6997c52c8d2$["official-base-table","property-light","family-rule"]$text_a0bde6997c52c8d2$::jsonb?id),jsonb_build_array('official-base-table')))),'[]'::jsonb) from jsonb_array_elements(payload#>'{rules,definition,capabilities}')cap),true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:c7cb954c8d7ea77c90cdd4cb';
if not exists(select 1 from public.campaign_content_entries t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:c854a59e028f50e24ed1d734' and md5(to_jsonb(t)::text)='f9a89c7b22647ca1dd3443bbcf900dc7')then raise exception 'ITEM_TEXT_CONFLICT:ece:official:equipment:es:c854a59e028f50e24ed1d734';end if;update public.campaign_content_entries set payload=jsonb_set(payload,'{features}',$text_6fb68522b9bd82ca$[{"id":"official-2014-rule","kind":"other","name":"Reglas de la variante","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Mientras lleves puesto este anillo, el terreno difícil no te costará movimiento adicional. Además, la magia no podrá reducir tu velocidad ni dejarte apresado o paralizado.\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_6fb68522b9bd82ca$::jsonb,true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:c854a59e028f50e24ed1d734';
if not exists(select 1 from public.campaign_content_entries t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:cad362e9a0790605f65af7ae' and md5(to_jsonb(t)::text)='f678c2ae621870e7e1b394e22594a558')then raise exception 'ITEM_TEXT_CONFLICT:ece:official:equipment:es:cad362e9a0790605f65af7ae';end if;update public.campaign_content_entries set payload=jsonb_set(jsonb_set(payload,'{features}',$text_e1efd99463b4d636$[{"id":"official-2014-rule","kind":"other","name":"Reglas de la variante","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Recibes un bonificador de +1 a las tiradas de ataque y de daño que hagas con esta arma mágica. Además, mientras tengas sintonización con ella, tus puntos de golpe máximos aumentan en 1 por cada nivel que hayas alcanzado.\n\nMaldición. Esta hacha está maldita y, al sintonizarte con ella, te afectará la maldición. Mientras sufras la maldición, no querrás deshacerte voluntariamente del hacha y la mantendrás siempre a tu alcance. También tendrás desventaja en las tiradas de ataque con otras armas, a menos que no haya ningún enemigo que puedas ver u oír a 18 m o menos de ti.\n\nCuando una criatura hostil te haga daño, si tienes el hacha en tu posesión, deberás superar una tirada de salvación de Sabiduría con CD 15 o sucumbirás a una furia berserk. Mientras estés bajo sus efectos, deberás utilizar tu acción cada asalto para atacar a la criatura que tengas más cerca con el hacha. Si puedes realizar ataques adicionales como parte de la acción de atacar, los utilizarás para atacar a la siguiente criatura más próxima tras derrotar a tu objetivo actual. Si tienes varios objetivos posibles, atacarás a uno al azar. Seguirás en ese estado hasta que comiences tu turno y no haya criaturas que puedas ver u oír a 18 m o menos de ti.\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_e1efd99463b4d636$::jsonb,true),'{rules,personalDescription}',$text_a5d59301b3113214$"Obtienes una bonificación de +1 a las tiradas de ataque y daño realizadas con esta arma mágica. Además, mientras estés en sintonía con esta arma, tu máximo de puntos de vida aumenta en 1 por cada nivel que hayas alcanzado.\n\nMaldición. Esta arma está maldita, y al acostumbrarte a ella, la maldición se extiende a ti. Mientras permanezcas maldito, no estarás dispuesto a desprenderte de ella, manteniéndola a tu alcance en todo momento. También tienes Desventaja en las tiradas de ataque con armas distintas a esta. Siempre que otra criatura te dañe mientras el arma esté en tu posesión, debes superar una tirada de salvación de Sabiduría CD 15 o entrarás en estado de rabieta. Este estado de rabieta termina cuando comienzas tu turno y no hay criaturas a 60 pies o menos de ti que puedas ver u oír. Mientras estás en estado de rabieta, consideras a la criatura más cercana a ti que puedas ver u oír como tu enemiga. Si hay varias criaturas posibles, elige una al azar. En cada uno de tus turnos, debes acercarte lo más posible a la criatura y realizar la acción de Ataque, apuntando a la criatura. Si no puedes acercarte lo suficiente a la criatura para atacarla con el arma, tu turno termina después de haber usado todo tu movimiento disponible. Si la criatura muere o ya no puedes verla ni oírla, la siguiente criatura más cercana que puedas ver u oír se convierte en tu nuevo objetivo."$text_a5d59301b3113214$::jsonb,true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:cad362e9a0790605f65af7ae';
if not exists(select 1 from public.campaign_content_entries t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:cb06ceb25f2b8c9a2ef8e087' and md5(to_jsonb(t)::text)='c18eba0adb3a7e8e94c11a8afa6aa67c')then raise exception 'ITEM_TEXT_CONFLICT:ece:official:equipment:es:cb06ceb25f2b8c9a2ef8e087';end if;update public.campaign_content_entries set payload=jsonb_set(payload,'{features}',$text_f05deeaf62894d19$[{"id":"official-2014-rule","kind":"other","name":"Reglas de la variante","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Este frasco de cristal, de 7,5 cm de diámetro, contiene 1d4 + 1 dosis de una mezcla espesa que huele ligeramente a aloe. El frasco y su contenido pesan 250 g.\n\nComo acción, una dosis del ungüento puede tragarse o aplicarse en la piel. La criatura que la reciba recuperará 2d8 + 2 puntos de golpe, dejará de estar envenenada y se curará de cualquier enfermedad.\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_f05deeaf62894d19$::jsonb,true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:cb06ceb25f2b8c9a2ef8e087';
if not exists(select 1 from public.campaign_content_entries t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:cb25f6558815b4e93185bb43' and md5(to_jsonb(t)::text)='ec699c2e7512408a7c7b5153129523b6')then raise exception 'ITEM_TEXT_CONFLICT:ece:official:equipment:es:cb25f6558815b4e93185bb43';end if;update public.campaign_content_entries set payload=jsonb_set(jsonb_set(jsonb_set(payload,'{description}',$text_e6013f2a47c339f3$"Objeto · Precio base · Peso\nPluma (para escribir) · 2 pc · —\n\nEsta obra incluye materiales extraídos del Documento de referencia del sistema 5.1 (‘SRD 5.1’) de Wizards of the Coast LLC, que está disponible en https://dnd.wizards.com/es/resources/systems-reference-document. El SRD 5.1 tiene la licencia Creative Commons Atribución/Reconocimiento 4.0 Licencia Pública Internacional, que está disponible en https://creativecommons.org/licenses/by/4.0/legalcode.es."$text_e6013f2a47c339f3$::jsonb,true),'{rules,definition,description}',$text_d81ecc59fcab73d4$[{"id":"official-table","rows":[["Pluma (para escribir)","2 pc","—"]],"type":"table","columns":["Objeto","Precio base","Peso"],"section":"description","sourceIds":["srd-5.1-en-equipment"],"provenance":"reviewed-translation"}]$text_d81ecc59fcab73d4$::jsonb,true),'{rules,definition,capabilities}',(select coalesce(jsonb_agg(cap||jsonb_build_object('textBlockIds',coalesce((select jsonb_agg(id) from jsonb_array_elements_text(cap->'textBlockIds')id where $text_b507874e9dab9bc1$["official-table"]$text_b507874e9dab9bc1$::jsonb?id),jsonb_build_array('official-table')))),'[]'::jsonb) from jsonb_array_elements(payload#>'{rules,definition,capabilities}')cap),true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:cb25f6558815b4e93185bb43';
if not exists(select 1 from public.campaign_content_entries t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:cb90976a4748db28834a8e62' and md5(to_jsonb(t)::text)='99759548f59b7c75dc0b51f15e6f1682')then raise exception 'ITEM_TEXT_CONFLICT:ece:official:equipment:es:cb90976a4748db28834a8e62';end if;update public.campaign_content_entries set payload=jsonb_set(jsonb_set(jsonb_set(jsonb_set(payload,'{description}',$text_f6dd41d6d6cb54a8$"Objeto · Precio base · Peso\nHerramientas de herrero · 20 po · 8 lb\n\nHerramientas de artesano. Estas herramientas especiales consisten en los objetos necesarios para llevar a cabo las tareas propias de un oficio. La tabla muestra ejemplos de las herramientas más habituales que proporcionan los útiles apropiados para una profesión concreta. La competencia con las herramientas de un oficio te permite sumar tu bonificador por competencia a cualquier prueba de característica que hagas con dichas herramientas, siempre y cuando las emplees en tareas de la profesión correspondiente. Cada tipo de herramientas de artesano requiere su propia competencia independiente.\n\nLas herramientas te permiten realizar algo que de otra forma estaría fuera de tu alcance, como fabricar o reparar un objeto, falsificar un documento o forzar una cerradura. Tu raza, clase, trasfondo o dotes pueden hacerte competente con ciertas herramientas. La competencia con una herramienta te permite sumar tu bonificador por competencia a cualquier prueba de característica que hagas con dicha herramienta. Hay que tener en cuenta que el uso de herramientas no está atado a una única característica, ya que la competencia con ellas representa un conocimiento amplio sobre su empleo. De este modo, tu GM podría pedirte que realices una prueba de Destreza para tallar detalles delicados con unas herramientas de ebanista, mientras que esculpir algo a partir de una madera especialmente dura podría requerir una prueba de Fuerza.\n\nEsta obra incluye materiales extraídos del Documento de referencia del sistema 5.1 (‘SRD 5.1’) de Wizards of the Coast LLC, que está disponible en https://dnd.wizards.com/es/resources/systems-reference-document. El SRD 5.1 tiene la licencia Creative Commons Atribución/Reconocimiento 4.0 Licencia Pública Internacional, que está disponible en https://creativecommons.org/licenses/by/4.0/legalcode.es."$text_f6dd41d6d6cb54a8$::jsonb,true),'{features}',$text_2b2bca0e5c7a5789$[{"id":"mundane-use","kind":"other","name":"Uso del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Herramientas de artesano. Estas herramientas especiales consisten en los objetos necesarios para llevar a cabo las tareas propias de un oficio. La tabla muestra ejemplos de las herramientas más habituales que proporcionan los útiles apropiados para una profesión concreta. La competencia con las herramientas de un oficio te permite sumar tu bonificador por competencia a cualquier prueba de característica que hagas con dichas herramientas, siempre y cuando las emplees en tareas de la profesión correspondiente. Cada tipo de herramientas de artesano requiere su propia competencia independiente.\n\nDuración: Mientras se cumplen los requisitos..","showInActions":false}]$text_2b2bca0e5c7a5789$::jsonb,true),'{rules,definition,description}',$text_fffb5f0692bd7e5b$[{"id":"official-table","rows":[["Herramientas de herrero","20 po","8 lb"]],"type":"table","columns":["Objeto","Precio base","Peso"],"section":"description","sourceIds":["srd-5.1-en-equipment"],"provenance":"reviewed-translation"},{"id":"official-rules-0","text":"Herramientas de artesano. Estas herramientas especiales consisten en los objetos necesarios para llevar a cabo las tareas propias de un oficio. La tabla muestra ejemplos de las herramientas más habituales que proporcionan los útiles apropiados para una profesión concreta. La competencia con las herramientas de un oficio te permite sumar tu bonificador por competencia a cualquier prueba de característica que hagas con dichas herramientas, siempre y cuando las emplees en tareas de la profesión correspondiente. Cada tipo de herramientas de artesano requiere su propia competencia independiente.","type":"paragraph","section":"rules","sourceIds":["srd-5.1-es-equipment"],"provenance":"official-spanish"},{"id":"tools-context-general","text":"Las herramientas te permiten realizar algo que de otra forma estaría fuera de tu alcance, como fabricar o reparar un objeto, falsificar un documento o forzar una cerradura. Tu raza, clase, trasfondo o dotes pueden hacerte competente con ciertas herramientas. La competencia con una herramienta te permite sumar tu bonificador por competencia a cualquier prueba de característica que hagas con dicha herramienta. Hay que tener en cuenta que el uso de herramientas no está atado a una única característica, ya que la competencia con ellas representa un conocimiento amplio sobre su empleo. De este modo, tu GM podría pedirte que realices una prueba de Destreza para tallar detalles delicados con unas herramientas de ebanista, mientras que esculpir algo a partir de una madera especialmente dura podría requerir una prueba de Fuerza.","type":"paragraph","section":"rules","sourceIds":["srd-5.1-es-tools-context"],"provenance":"official-spanish"}]$text_fffb5f0692bd7e5b$::jsonb,true),'{rules,definition,capabilities}',(select coalesce(jsonb_agg(cap||jsonb_build_object('textBlockIds',coalesce((select jsonb_agg(id) from jsonb_array_elements_text(cap->'textBlockIds')id where $text_ee76d66ef5f1117d$["official-table","official-rules-0","tools-context-general"]$text_ee76d66ef5f1117d$::jsonb?id),jsonb_build_array('official-table')))),'[]'::jsonb) from jsonb_array_elements(payload#>'{rules,definition,capabilities}')cap),true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:cb90976a4748db28834a8e62';
if not exists(select 1 from public.campaign_content_entries t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:cbfbeb4aafdeb42aa1660850' and md5(to_jsonb(t)::text)='efdd1a8d3ce69988233d6555e3654b5c')then raise exception 'ITEM_TEXT_CONFLICT:ece:official:equipment:es:cbfbeb4aafdeb42aa1660850';end if;update public.campaign_content_entries set payload=jsonb_set(jsonb_set(payload,'{features}',$text_cb1746b6035208e3$[{"id":"official-2014-rule","kind":"other","name":"Reglas de la variante","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Este bastón se puede usar a modo de bastón mágico que otorga un bonificador de +3 a las tiradas de ataque y de daño realizadas con él.\n\nEl bastón tiene 10 cargas. Cuando impactes con un ataque cuerpo a cuerpo con él, podrás gastar hasta 3 cargas. Por cada carga empleada, el objetivo recibirá 1d6 de daño de fuerza adicional. El bastón recupera 1d6 + 4 cargas empleadas cada día, al amanecer. Si gastas la última carga, tira 1d20. Si el resultado es 1, el bastón se convierte en un bastón no mágico.\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_cb1746b6035208e3$::jsonb,true),'{rules,personalDescription}',$text_4a5034accb59b926$"Este bastón se puede utilizar como un bastón mágico que otorga una bonificación de +3 a las tiradas de ataque y daño realizadas con él. El bastón tiene 10 cargas. Cuando impactas con un ataque cuerpo a cuerpo usándolo, puedes gastar hasta 3 cargas. Por cada carga que gastes, el objetivo sufre 1d6 de daño de Fuerza adicional.\n\nRecuperación de cargas. El bastón recupera 1d6 + 4 cargas gastadas diariamente al amanecer. Si gastas la última carga, tira 1d20. Con un 1, el bastón se convierte en un bastón no mágico."$text_4a5034accb59b926$::jsonb,true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:cbfbeb4aafdeb42aa1660850';
if not exists(select 1 from public.campaign_content_entries t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:cc6d904679038c3cb3a54a64' and md5(to_jsonb(t)::text)='c4524974fbfc11a2176ed22760ff610d')then raise exception 'ITEM_TEXT_CONFLICT:ece:official:equipment:es:cc6d904679038c3cb3a54a64';end if;update public.campaign_content_entries set payload=jsonb_set(payload,'{features}',$text_db5c645ac61c50c7$[{"id":"official-2014-rule","kind":"other","name":"Reglas de la variante","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Mientras sostengas este abanico, podrás utilizar una acción para lanzar ráfaga de viento (CD de salvación 13) desde él. Una vez utilizado, no debería volver a emplearse hasta el siguiente amanecer. Cada vez que se vuelva a utilizar hasta ese momento, habrá una probabilidad acumulativa del 20 % de que no funcione y se haga jirones inútiles y no mágicos.\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_db5c645ac61c50c7$::jsonb,true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:cc6d904679038c3cb3a54a64';

update public.campaigns set state_revision=state_revision+1,state_updated_at=statement_timestamp(),updated_at=statement_timestamp() where id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd';end $text$;select 8 as batch,39 as rows,(select state_revision from public.campaigns where id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd')as revision;commit;